$wt="D:\repository\门户\zhi2-web-admin-wt-chart-font-clarity"
$line = (Get-Content "$wt\src\views\property\marketMonitor\assets\dashboard.css" -Encoding UTF8)[2]
# print only the --font-sans and --font-mono tokens with boundaries
foreach($tok in @('--font-sans','--font-mono')){
  $i=$line.IndexOf($tok)
  if($i -ge 0){ Write-Host "=== $tok ==="; Write-Host $line.Substring($i, [Math]::Min(180, $line.Length-$i)) }
}

